// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 drugs, uint256 ethAmount) internal {
        ethAmount = bound(ethAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= ethAmount);
        vm.assume(c.marketDrugs() == 0);
        try c.seedMarket{value: ethAmount}(drugs) {} catch { return; }
        assertTrue(c.marketDrugs() == drugs ? c.initialized() == true : true);
    }

    function testFuzz_run(uint256 drugs, uint256 ethAmount) public {
        _run(drugs, ethAmount);
    }

    receive() external payable {}
}
